// Secure version of the application
// Addresses common Node.js security vulnerabilities

const express = require('express');
const helmet = require('helmet');
const app = express();

// Load environment variables
require('dotenv').config();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Security middleware
app.use(helmet());

// Health endpoint with basic security
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

// Users endpoint with basic security
app.get('/users', (req, res) => {
  try {
    // In a production application, this data would come from a database
    // and be retrieved via a service layer with proper data access controls
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output - even with mock data
    const sanitizedUsers = mockUsers.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

// Basic error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.stack);
  res.status(500).json({ status: 'error', message: 'Something went wrong!' });
});

app.listen(PORT, HOST, () => {
  console.log(`Secure server running on ${HOST}:${PORT}`);
});

module.exports = app;

